import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";
import { initialTransition, isUnhandled, transition } from "xstate";
import type { AnyStateMachine, EventFromLogic, SnapshotFrom } from "xstate";

const isIntent = Schema.is(Schema.Struct({ type: Schema.Literals(["patch", "notice.post", "notice.resolve", "input.send", "place.countCatchUp", "place.release", "procedure.start"]) }));

export const initial = <M extends AnyStateMachine>(...input: Parameters<typeof initialTransition<M>>) => {
  const [snapshot, effects] = initialTransition(...input);

  if (effects.length > 0) { throw new Error("Durable machines must initialize without effects"); }

  return snapshot;
};

export const decideMachine = <M extends AnyStateMachine>(machine: M, snapshot: SnapshotFrom<M>, event: EventFromLogic<M>) => {
  const result = transition(machine, snapshot, event);

  for (const effect of result[1]) {
    if (effect.kind !== "emit" || !isIntent(effect.event)) { throw new Error(`Durable machines cannot execute ${effect.type}`); }
  }

  return isUnhandled(snapshot, result) ? Option.none() : Option.some({ snapshot: result[0], intents: result[1].map((effect) => {
    if (effect.kind !== "emit") { throw new Error("Expected an emitted intent"); }

    return effect.event;
  }) });
};

// The supplied apply owns the single transaction, including CAS, journal and durable intents.
export const commit = <Row, A, E, R>(
  read: Effect.Effect<Row, E, R>,
  persist: (row: Row) => Effect.Effect<A, E, R>,
  conflict: (error: E) => boolean
): Effect.Effect<A, E, R> => {
  const attempt = Effect.gen(function* attempt() {
    const row = yield* read;

    return yield* persist(row);
  });

  return attempt.pipe(Effect.catchIf(conflict, () => attempt));
};
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import { createMachine, initialTransition, types } from "xstate";
import { describe, expect, it } from "vite-plus/test";

import { copyMachine, decide as copyDecision } from "../copies/copy.machine.ts";
import { COPY_STATES } from "../copies/repo.ts";
import { getShortestPaths } from "./graph.test-util.ts";
import { commit, decideMachine as decide, initial } from "./kernel.ts";

const facts = { settledBy: null, baseSha: "base", headSha: null, handbackRef: null, handbackSha: null, handbackTree: null };
const persist = (row: number) => row === 1 ? Effect.fail("conflict") : Effect.succeed(row);

describe("durable machine kernel", () => {
it("generates copy paths from the machine and replays them", () => {
  const events = [
    { type: "PROVISIONED" as const, contained: true, owned: true, baseMatches: true, clean: true },
    { type: "WORKER_FINISHED" as const, writeLeases: 0, headSha: "head" },
    { type: "LANDED" as const, recorded: true },
    { type: "RETENTION_ELAPSED" as const, idleMs: 10, policyMs: 1, leases: 0, covered: true },
    { type: "START_REMOVAL" as const, proof: { contained: true, owned: true, noLeases: true, noClaims: true, notOpen: true, noDatabase: true, covered: true } },
    { type: "HANDED_BACK" as const, ref: "refs/orca/c", sha: "head", tree: "tree", current: true },
    { type: "PROVED_EMPTY" as const, headSha: "base", clean: true },
    { type: "OWNER_DISCARDED" as const, approved: true },
    { type: "PROVISION_FAILED" as const, contained: true, owned: true },
    { type: "REMOVED" as const }, { type: "FAILED" as const },
  ];

  const paths = getShortestPaths(copyMachine, { input: facts, events, serializeState: (snapshot) => snapshot.value });

  expect(paths.map((path) => path.state.value).toSorted()).toStrictEqual([...COPY_STATES].toSorted());

  for (const path of paths) {
    let snapshot = initial(copyMachine, facts);

    for (const step of path.steps.slice(1)) {
      const decision = Option.getOrThrow(decide(copyMachine, snapshot, step.event));
      ({ snapshot } = decision);
    }

    expect(snapshot.value).toBe(path.state.value);
  }

  for (const state of COPY_STATES) {
    for (const event of events) {
      const result = copyDecision(state, facts, event);

      expect(Option.isOption(result)).toBe(true);
    }
  }

  for (const state of ["removed", "quarantined"] as const) {
    for (const event of events) { expect(Option.isNone(copyDecision(state, facts, event))).toBe(true); }
  }
});

it("re-reads once on a conflict and propagates a second conflict", async () => {
  let reads = 0;

  const read = Effect.sync(() => {
    reads += 1;

    return reads;
  });

  await expect(Effect.runPromise(commit(read, persist, (error) => error === "conflict"))).resolves.toBe(2);
  reads = 0;
  await expect(Effect.runPromise(Effect.flip(commit(read, () => Effect.fail("conflict"), () => true)))).resolves.toBe("conflict");
  expect(reads).toBe(2);
});

it("rejects executable effects instead of running them", () => {
  const machine = createMachine({
    schemas: { events: { GO: types<undefined>() } }, initial: "idle",
    states: { idle: { on: { GO: (_args, enq) => { enq(() => {});

 return { target: "done" }; } } }, done: {} },
  });

  expect(() => decide(machine, initialTransition(machine)[0], { type: "GO" })).toThrow("Durable machines cannot execute");
});
});

import type { LandingBatch, LandingState } from "@orca/contracts/core/landing";
import type { WorkItem } from "@orca/contracts/core/work";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import { createMachine, types } from "xstate";

import { decideMachine } from "../machine/kernel.ts";
import type { Notices } from "../notices/Notices.ts";
import type { LandingRepo } from "./repo.ts";
import { notifyStuck } from "./stuck.ts";

export type LandingEvent =
  | {
      readonly type:
        | "SELECTED"
        | "GATHERED"
        | "CATCH_UP_BLOCKED"
        | "CHECKS_PASSED"
        | "PUBLISH"
        | "PREPARED"
        | "PR_OPENED"
        | "PR_MERGED"
        | "PUBLISHED"
        | "NOTHING_READY"
        | "INTERNAL_FAULT"
        | "REMOVED"
        | "OWNER_PARKED"
        | "OWNER_APPROVED"
        | "LINKED"
        | "WAITING";
    }
  | { readonly type: "DECIDED"; readonly level: "orca" | "owner" | "hold" }
  | { readonly type: "MAIN_MOVED_CLEAN"; readonly round: number }
  | { readonly type: "CLASH"; readonly main: string }
  | {
      readonly type: "CHECK_FAILED";
      readonly cause: "item" | "main" | "unknown";
    }
  | {
      readonly type: "REVIEW";
      readonly verdict: "ready" | "fixes" | "escalate" | "unavailable";
    };

const common = {
  LINKED: {},
  INTERNAL_FAULT: { target: "failed" as const },
  REMOVED: { target: "removed" as const },
};

const clean = ({ event }: { event: { round: number } }) => ({
  target: event.round < 3 ? ("merging" as const) : ("failed" as const),
  context: { approved_at: null },
});

export const landingMachine = createMachine({
  id: "landing",
  schemas: {
    context: types<Pick<LandingBatch, "approved_at">>(),
    input: types<Pick<LandingBatch, "approved_at">>(),
    events: {
      SELECTED: types<undefined>(),
      GATHERED: types<undefined>(),
      CATCH_UP_BLOCKED: types<undefined>(),
      CHECKS_PASSED: types<undefined>(),
      PUBLISH: types<undefined>(),
      PREPARED: types<undefined>(),
