      "omitted-value|/schemas/events/VERIFIED",
      "omitted-value|/schemas/events/VERIFY_FAILED",
    ],
  },
];

describe("machine graph diagnostics", () => {
  it.each(baselines)("$name has only the pinned analysis and serialization limitations", ({ machine, targets, serialization }) => {
    const { analysis } = toDirectedGraph(machine);

