import { mkdtemp, realpath } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { resolve, join } from 'node:path'
import { startCanvas } from './canvas-host.mjs'
import { canvasRoot } from './canvas-root.mjs'
import { moduleReviewAdapter } from './module-adapter.mjs'

const root = resolve(canvasRoot, '../..')
const store = await realpath(await mkdtemp(join(tmpdir(), 'civic-self-debug-')))
const server = await startCanvas({ project: join(root, 'civic.json'), store, port: 0, logLevel: 'silent' })
const origin = `http://127.0.0.1:${server.httpServer.address().port}`
const browser = await moduleReviewAdapter.launchFixtureBrowser()
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', error => console.log('pageerror', error.message))
page.on('console', msg => { if (msg.type() === 'error') console.log('console', msg.text().slice(0, 300)) })
for (const id of ['civic.picker', 'civic.canvas', 'civic.settings']) {
  await page.goto(`${origin}/review-frame.html?scenario=${id}&width=1440&height=900`)
  await page.waitForTimeout(4000)
  const buttons = await page.getByRole('button').evaluateAll(els => els.slice(0, 15).map(el => el.getAttribute('aria-label') || el.textContent.trim().slice(0, 40)))
  console.log(id, JSON.stringify(buttons), (await page.locator('body').innerText()).slice(0, 300).replace(/\n+/g, ' | '))
}
await browser.close(); await server.close()

